    commitExists,
    commitStagedChanges,
    commitTrackedPaths,
    ensureInsideRoot,
    hasStagedChanges,
    hasPendingPush,
    isCommitAncestor,
    isGitIndexLockError,
    listBranches,
    pathExists,
    parseShortStat,
    push,
    readFileAtCommit,
    resolveCommitMetadata,
    resolveLocalProject,
    requireRootPath,
    runCommand,
    runGit,
